//! Actual raw-page lifecycle DATA. Only its private host can certify two CODE EOFs.
use crate::{lifecycle_policy::{self as policy,FileFacts,Patterns},state_schema_data::{self as schema,Schema},captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_allow_annotations::Operation,key_policy_control::{self as kc,Control},reactive_raw_policy_pages::RawPolicyPages,lint::Site};
use std::{sync::Arc,io};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}checked(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
pub struct LifecycleData{sites:Vec<Site>,notes:Vec<String>}
impl LifecycleData{pub fn sites(&self)->&[Site]{&self.sites}pub fn notes(&self)->&[String]{&self.notes}pub fn metadata(&self)->&'static crate::lint::Meta{&policy::META}pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.notes.capacity().checked_mul(std::mem::size_of::<String>())?)?;for site in &self.sites{for word in [&site.rule,&site.rel,&site.msg,&site.key,&site.ident]{n=n.checked_add(word.capacity())?;}}for note in &self.notes{n=n.checked_add(note.capacity())?;}Some(n)}pub fn serialize_data<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeTuple;let mut rows=serializer.serialize_tuple(2)?;rows.serialize_element(&self.sites)?;rows.serialize_element(&self.notes)?;rows.end()}}
pub fn collect_from_pages(pages:&dyn RawPolicyPages,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<LifecycleData,Failure>{checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let keep=&phase.budget;let pending=(||{let mut work=Operation{budget:keep,poll};let mut schema=Schema::default();let all=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let pending=(||{checked(local,poll)?;views.code()?;let file=views.source_file()?;let mut temporary=Operation{budget:local,poll};schema::parse_file_using(relative,file.code(),&mut schema.decls,&mut schema.latent,&mut work,&mut temporary)?;Ok(true)})();finish(pending,local,poll)})?;if !all{return Err("lifecycle schema source stopped before actual CODE EOF".into())}
 kc::reserve(&mut work,||Some(4096))?;let patterns=Patterns::new();let mut files=Vec::new();let selected=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let pending=(||{checked(local,poll)?;views.code()?;let file=views.source_file()?;let mut temporary=Operation{budget:local,poll};let bodies=policy::scan_using(file.code(),&patterns,&mut work,&mut temporary)?;policy::row(&mut work,&mut files)?;files.push(FileFacts{relative:kc::own(&mut work,relative)?,bodies});Ok(true)})();finish(pending,local,poll)})?;if !selected{return Err("lifecycle selected source stopped before actual CODE EOF".into())}
 let output=std::cell::RefCell::new(LifecycleData{sites:Vec::new(),notes:Vec::new()});policy::judge_using(&schema,&files,&patterns,&mut work,&mut|rule,relative,line,message,c|{let mut out=output.borrow_mut();policy::row(c,&mut out.sites)?;out.sites.push(Site{rule:kc::own(c,rule)?,rel:kc::own(c,relative)?,line,msg:message,key:String::new(),ident:String::new()});Ok(())},&mut|message,c|{let mut out=output.borrow_mut();policy::row(c,&mut out.notes)?;out.notes.push(message);Ok(())})?;checked(keep,poll)?;Ok(output.into_inner())})();let pending=finish(pending,keep,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"lifecycle returned capacity overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)}
